		set(LmdbNativeJaninoCodegen.SYNCHRONOUS_PROPERTY, "false");
		// This makes the dynamic compiled refusal deterministic, even if a shape was compiled in another test.
		set(LmdbNativeJaninoCodegen.THRESHOLD_ROWS_PROPERTY, Long.toString(Long.MAX_VALUE));
		set(LmdbNativeKernelInterpreter.ENABLED_PROPERTY, "true");
		set(LmdbNativeKernelInterpreter.WARMUP_PROPERTY, "true");
		set(LmdbNativeKernelLowering.OUTPUT_MODS_PROPERTY, "true");
		set(LmdbNativeKernelLowering.SCAN_SOURCES_PROPERTY, "true");
		set(LmdbNativeKernelLowering.HASH_JOIN_PROPERTY, "false");
		set(LmdbNativeKernelIr.RESUMABLE_PROPERTY, "true");
		set("rdf4j.lmdb.parallel.enabled", "false");
